/// One program of a draw pipeline: its QPU code and uniform list, and
/// the prog_data the shader state record reads.
pub struct DrawProgram<P: 'static> {
    pub qpu: &'static [u64],
    pub uniforms: &'static [U],
    pub prog: P,
}

/// The pipeline v3dv builds from draw/rect.vert and draw/draw.frag for
/// one item kind (draw.frag's specialization constant 0).
pub struct DrawPipeline {
    pub kind: u32,
    pub vs: &'static DrawProgram<crate::v3d_draw::VsProgData>,
    /// The binning variant of the vertex shader.
    pub cs: &'static DrawProgram<crate::v3d_draw::VsProgData>,
    pub fs: &'static DrawProgram<crate::v3d_draw::FsProgData>,
}

